ProjectALife.DialogueShards["scenes_misc_5"] = {
{"ordinary_rescue_names","memory",2,"reg=rescue|st=friendly,neutral",{1,"I remember the names better than the faces",2,"From the calls?",1,"Yeah, keep saying them in my head",2,"Somebody should remember, just leave some room in there for yourself"}},
{"s13_sf_not_naming_001","mission",2,"reg=elite|role=elite_delta|tmp=veteran|world=vehicle",{1,"You going to write it up?",2,"Write what up?",1,"Right, okay",2,"There's nothing to write, we drove out, we drove back, the truck used forty gallons - log the gallons"}},
{"s13_sf_never_there_002","mission",2,"reg=elite|role=elite_delta,elite_operator",{1,"Somebody asked me where we were on the night of the eleventh",2,"And?",1,"I said Rosewood",2,"We weren't in Rosewood",1,"No, and now two of us have said Rosewood, so let's both keep saying Rosewood"}},
{"s13_sf_construction_003","mission",2,"reg=elite|mood=funny",{1,"Lady at the well asked me what I did before all this",2,"What'd you tell her?",1,"Construction",2,"You've said construction in three counties now, learn a second trade"}},
{"s13_sf_three_words_004","mission",3,"reg=elite|tmp=veteran",{1,"How much can we tell the Guard sergeant at the wire?",2,"Three things, we're American, we're going north, we'll be back Thursday",3,"He'll ask a fourth",2,"Then he asks and I say I can't, and he lets it go - they always let it go, that's the part that bothers me"}},
{"s13_sf_after_action_005","mission",2,"reg=elite|mood=grim",{1,"There's no after action on this one",2,"There's always an after action",1,"Not with nobody to brief and no authority left in the state - it goes in my head, that's the archive now"}},
{"s13_delta_two_words_024","mission",2,"reg=elite|role=elite_delta",{1,"You want the truth or you want it short?",2,"Short",1,"It's done, everybody's accounted for, that's all you get and it ain't 'cause I'm being cute"}},
{"s13_delta_no_names_026","mission",2,"reg=elite|role=elite_delta|mood=sad",{1,"You never say his name",2,"I say his name at home",1,"That ain't the same thing",2,"No, it ain't - it's the version I can do out here"}},
{"s13_delta_squadron_027","mission",2,"reg=elite|role=elite_delta|world=cars",{1,"There's supposed to be a squadron behind you",2,"There's supposed to be a lot of things",1,"So what have you actually got?",2,"Four men, two trucks, and a radio that answers every third day - same as you, just quieter about it"}},
{"s13_delta_selection_028","mission",2,"reg=elite|role=elite_delta|world=rain",{1,"What's the hardest thing you ever did?",2,"Walked a mountain in the rain with a pack while a man wrote numbers on a clipboard",1,"That's it? Not, you know - anything else?",2,"The mountain's where I found out about myself, the rest was just work"}},
{"s13_delta_relaxed_grooming_029","mission",2,"reg=elite|role=elite_delta",{1,"You don't salute, you don't sir anybody, you don't wear a patch",2,"I say sir to old men and to preachers, nobody's ever complained about it"}},
{"s13_delta_wont_land_030","mission",3,"reg=elite|mood=angry",{1,"Bird was supposed to come into the ballfield",2,"It didn't",1,"It came, circled twice and left, that pilot's got fuel math same as we do",3,"So we're walking",1,"We're walking - forty-one miles, start now, complain later"}},
{"s13_sf_quiet_job_052","mission",2,"reg=elite|tmp=veteran",{1,"Best thing we did all month and nobody will ever hear about it",2,"Which one?",1,"The one where we got there early and nothing happened - that's the job and it don't make a story"}},
{"s13_sf_kid_asks_054","mission",2,"reg=elite|mood=warm",{1,"Boy at the camp asked me if I was a Green Beret",2,"What'd you say?",1,"Said I work for the government and I'm here about the water - which is the truth twice over"}},
{"s13_sf_close_out_056","mission",3,"reg=elite|tmp=veteran",{1,"Last thing, nobody here ever says what we did on the eleventh",2,"Copy",3,"Copy",1,"And in ten years, if somebody buys you a beer and asks, you still don't - not for a beer, not for a book",2,"Understood"}},
{"fw_ld4_topics_b_0001","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4|world=trees",{1,"Shh- you hear something?",2,"Hear what?",1,"Something moved out there, by the tree line",2,"A deer, probably",1,"Deer don't walk on two legs",2,"...wake the others, quietly"}},
{"fw_ld4_topics_b_0002","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"I can't keep my eyes open",2,"Stand up, walk around",1,"I tried, my legs fell asleep",2,"Pinch yourself",1,"I did, I pinched, I'm still sleepy",2,"Then talk, talk to me, tell me about your day"}},
{"fw_ld4_topics_b_0003","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"What's the time?",2,"Past midnight",1,"Is it? It feels like four",2,"It always feels like four on watch",1,"I hate this part"}},
{"fw_ld4_topics_b_0004","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"See any stars?",2,"A few, between the clouds",1,"Make a wish",2,"I wish for a cheeseburger",1,"That's the same wish as last night",2,"And I'll wish it again tomorrow"}},
{"fw_ld4_topics_b_0005","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Shhh, listen",2,"What?",1,"Footsteps, slow, dragging",2,"How many?",1,"One, I think, just one",2,"Get the bat, get the bat, no noise"}},
{"fw_ld4_topics_b_0006","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Your turn",2,"Already?",1,"I've been up for four hours",2,"Sorry, I fell asleep, I'm sorry, I'm sorry",1,"Just take the watch, it's fine"}},
{"fw_ld4_topics_b_0007","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Look at the moon",2,"It's beautiful",1,"It's the same moon, you know, as before",2,"That's the only thing that hasn't changed"}},
{"fw_ld4_topics_b_0008","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Think they know we're here?",2,"Who?",1,"Anyone, anything",2,"If they did, we'd be dead already",1,"Comforting, thanks"}},
{"fw_ld4_topics_b_0009","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"I hate the dark",2,"Everyone hates the dark",1,"It used to be fine, I slept with the lights off",2,"Now every shadow has teeth, I know"}},
{"fw_ld4_topics_b_0010","night_watch",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Did you eat?",2,"Not yet",1,"Wish I had something to split with you",2,"I'm okay",1,"Don't pretend it doesn't matter. Being hungry makes everything harder"}},
{"fw_ld4_topics_b_0011","night_watch",2,"reg=law,swat|hour=21,4",{1,"All quiet?",2,"Quiet",1,"I hate when it's quiet",2,"Quiet means we live another hour",1,"That's one way to look at it"}},
{"fw_ld4_topics_b_0012","night_watch",2,"reg=law,swat|hour=21,4",{1,"Hold on. I want a second to look",2,"Distance?",1,"Fifty yards, moving slowly",2,"Hold fire, let it come, don't waste a round"}},
{"fw_ld4_topics_b_0013","night_watch",2,"reg=military,elite|hour=21,4",{1,"Sector clear",2,"Copy",1,"Wind's picking up",2,"Good, covers our noise",1,"And theirs",2,"Yeah, and theirs"}},
{"fw_ld4_topics_b_0014","night_watch",2,"reg=military,elite|hour=21,4",{1,"Private, are you awake?",2,"Yes, sir",1,"Your head's drooping",2,"It's the helmet, sir, it's heavy",1,"Splash some water on your face, I'll take it from here"}},
{"fw_ld4_topics_b_0015","night_watch",2,"reg=outlaw,raider,gang,club,crime,prison|hour=21,4",{1,"Anyone on watch?",2,"I am",1,"You're asleep",2,"I'm resting my eyes",1,"While we're getting killed",2,"Fine, fine, I'm up, who's there?"}},
{"s10_watch_screech_owl_001","night_watch",2,"reg=civilian,family|tmp=fresh|hour=21,5|mood=fear",{1,"What was that?",2,"Owl",1,"No owl sounds like that",2,"Screech owl, granddaddy used to do that call under our window to scare us",1,"Well, it's still working"}},
{"s10_watch_satellite_file_002","night_watch",2,"reg=military|hour=22,4|mood=funny",{1,"Light moving across up there - no blinking",2,"Satellite",1,"So somebody up there is still taking pictures of us",2,"Smile, then - give 'em something nice for the file"}},
{"s10_watch_lighter_click_003","night_watch",2,"reg=raider,gang,prison|hour=21,4|mood=angry|world=water",{1,"Put that lighter away",2,"I ain't lighting nothing, just clicking it",1,"Every click's a spark somebody half a mile off can see - put it in your pocket or I'll put it in the creek"}},
{"s10_watch_graveyard_shift_004","night_watch",2,"reg=law|tmp=seasoned,veteran|hour=23,5|mood=grim",{1,"Graveyard shift, eleven to seven, worked it nine years straight",2,"You miss it?",1,"The name's a lot funnier now"}},
{"s10_watch_dog_then_army_005","night_watch",2,"reg=family|hour=21,2|mood=warm",{1,"She said her prayers tonight without me starting her off",2,"What'd she pray for?",1,"For the dog, then for the Army to hurry up, in that order",2,"Well, she's got her priorities"}},
{"s10_watch_six_heading_east_006","night_watch",2,"reg=elite|tmp=veteran|hour=21,5|mood=calm|world=trees",{1,"Movement - two hundred - tree line",2,"Count them",1,"Six - slow - heading east",2,"Let them pass",1,"Passing"}},
{"s10_watch_tier_sounds_007","night_watch",2,"reg=prison|hour=22,5|mood=grim|world=door",{1,"Inside, I knew every sound on the tier at night - who snored, who cried, which door stuck",2,"And out here?",1,"Out here I don't know a single one, that's what keeps me up"}},
{"s10_watch_horses_standing_008","night_watch",2,"reg=club,outlaw|hour=21,5|mood=funny",{1,"You think they sleep?",2,"They who?",1,"Them - out there, they just stand all night like horses",2,"Horses sleep standing up",1,"So maybe they're sleeping",2,"Go out there and wake one up, then, I'll hold the light"}},
{"s10_watch_earls_flashlight_009","night_watch",2,"reg=worker,civilian|hour=21,5|mood=warm",{1,"This was Earl's flashlight, night security at the plant, fourteen years",2,"Heavy thing",1,"Four D cells - Earl said the front end's a flashlight and the back end's a conversation"}},
{"s10_watch_be_specific_010","night_watch",2,"reg=gang,crime|hour=22,4|mood=funny|world=cars",{1,"Never heard the city this quiet",2,"No sirens, no bass out of the cars - nobody hollering on the corner",1,"I used to pray for quiet like this",2,"Should've been more specific"}},
{"s10_watch_pick_another_star_011","night_watch",2,"reg=family|role=family_elder,family_youth|hour=21,1|mood=sad",{1,"Find the dipper, follow the two stars on the end of the cup",2,"That bright one?",1,"That's north, that's the way to Louisville",2,"Can we use a different star?"}},
{"s10_watch_moms_number_012","night_watch",2,"reg=military|role=soldier_green,soldier|hour=22,5|mood=warm",{1,"Tell me your mom's phone number",2,"What for, man?",1,"So somebody else has it - in case, I'll tell you mine",2,"Area code six-one-four, then the rest of it - say it back to me twice"}},
{"s10_watch_decided_rain_013","night_watch",2,"reg=civilian,family,worker|tmp=seasoned|hour=21,5|mood=grim|world=rain",{1,"Rain's coming in sideways",2,"Good, they don't like the rain",1,"Who told you a thing like that?",2,"Nobody, I decided it, so I could keep standing out here"}},
{"s10_watch_cb_crying_man_014","night_watch",3,"reg=raider|tmp=predator|hour=0,4|mood=grim|world=road",{1,"Fella on the CB is crying for his wife again - every night around two",2,"Turn him up, he's a riot",3,"Turn him off",2,"Why? He's the best thing on",3,"'Cause I'm the one who took her off the road on Tuesday - turn it off"}},
{"s10_watch_station_tone_015","night_watch",2,"reg=rescue|role=rescue_firefighter,rescue_medical|hour=1,5|mood=warm",{1,"I still wake up for the station tone, three in the morning, sitting straight up",2,"There's no tone",1,"Nope, but I'm up, figured I'd take your watch",2,"I'll sit up with you a while anyhow"}},
{"s10_watch_lyle_negotiator_016","night_watch",2,"reg=swat,law|tmp=seasoned,veteran|hour=21,4|mood=grim",{1,"Lyle would've tried to talk 'em down",2,"Lyle talked a man out of a trailer after nine hours - man had his own mother in there",1,"Got her out, too, not a scratch",2,"Lyle's out there somewhere tonight, still talking, I bet - just not making sense"}},
{"s10_watch_count_start_over_017","night_watch",1,"reg=civilian,family|tmp=fresh|hour=0,5|mood=fear",{1,"Five hundred and one, five hundred and two",1,"Eyes open, pinch your arm - five hundred and, and what was it?",1,"Start over - one, nobody gets in on my count"}},
{"s10_watch_dog_never_wrong_018","night_watch",2,"reg=family,civilian|hour=21,5|mood=fear|world=vehicle",{1,"Dog's growling at the dark",2,"Growling at what?",1,"He won't say",2,"Go wake your brother, that dog was never once wrong about a car in the drive"}},
{"s10_watch_september_lightning_bug_019","night_watch",2,"reg=military,law|day=55,120|hour=21,4|mood=fear|world=fence,storm",{1,"Light, low, by the fence post",2,"Lightning bug",1,"It's September",2,"Then it's a real late lightning bug",1,"Or a cigarette - go wake the Sergeant - quiet"}},
{"s10_watch_chainsaw_snoring_020","night_watch",2,"reg=outlaw,civilian,family|role=family_elder,civilian_man,outlaw|hour=21,5|mood=sad",{1,"Forty years I slept next to a woman who snored like a chainsaw",2,"And now you can't sleep for the quiet",1,"No, now I sleep just fine, that's the part that gets me"}},
{"s10_watch_ridge_lamp_021","night_watch",2,"reg=civilian,family,worker|day=10,300|hour=21,2|mood=warm",{1,"That lamp's on over on the ridge again",2,"Every night about ten",1,"Should we signal 'em?",2,"Not yet, it's just nice knowing somebody else is up"}},
{"s10_watch_truth_then_dare_022","night_watch",2,"reg=gang,crime|hour=21,5|mood=funny",{1,"Truth or dare",2,"We're on watch",1,"Truth, then - what'd you really do with Marcus's money?",2,"Dare"}},
{"s12_bell_cedar_grove_eleven_001","night_watch",2,"reg=civilian,family|tmp=seasoned|hour=23,4|mood=fear",{1,"Bell at Cedar Grove went last night - eleven times",2,"Somebody calling folks in",1,"Eleven, though, nobody rings eleven - and there's nobody in that church, I been in that church"}},
{"s12_bell_three_in_morning_002","night_watch",2,"reg=civilian,worker|tmp=seasoned|hour=0,5|mood=grim",{1,"Little Bethel rang at three this morning, six of 'em, slow, like a funeral",2,"Rope's loose, wind gets in that steeple",1,"Wind don't count to six and quit"}},
{"s12_bell_chainsaw_south_007","night_watch",2,"reg=worker,civilian|tmp=seasoned|hour=0,6|mood=grim|world=water",{1,"There's a saw running somewhere south of the creek, two days now",2,"Somebody clearing blowdown",1,"A saw don't run two days, a tank's forty minutes - you do the arithmetic on that and tell me"}},
{"s12_bell_machine_hum_010","night_watch",2,"reg=military,elite|tmp=veteran|hour=23,5|mood=calm|world=generator",{1,"Generator hum, bearing about two seven zero, running since we got here",2,"Somebody's got fuel then",1,"Somebody's got fuel and no lights, four nights, no light anywhere on that bearing"}},
{"s12_mut_crickets_010","night_watch",1,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear|world=summer",{1,"No crickets - summer, and no crickets",1,"Well... guess I'll sit closer to the fire, then"}},
{"s12_mut_dog_wont_look_020","night_watch",1,"reg=civilian,family|tmp=seasoned|hour=21,2|mood=fear|world=trees",{1,"Look at the trees, Buck, go on - look at 'em",1,"Fine, then, we won't look at the trees"}},
{"s12_mut2_fires_answer_009","night_watch",1,"reg=civilian,worker|tmp=seasoned|hour=21,2|mood=grim",{1,"One Wednesday - three Thursday",1,"We ain't lighting another one, cold supper till I say different"}},
{"s12_mut2_porch_no_moths_023","night_watch",1,"reg=civilian,family|tmp=seasoned|hour=21,2|mood=grim",{1,"Hour that bulb's been on and not a moth on it",1,"Every July of my life that thing's been a ball of bugs by nine"}},
{"s12_tracks_dog_wont_look_007","night_watch",2,"reg=family,civilian|tmp=seasoned|hour=20,2|mood=fear|world=trees",{1,"Buck won't look at them trees",2,"He's old",1,"He'll look at me, he'll look at the fire - he will not look at them trees"}},
{"s12_tracks_no_crickets_009","night_watch",2,"reg=civilian,family|tmp=seasoned|hour=21,3|mood=fear|world=summer",{1,"Sat out here ten minutes before it got through to me",2,"What",1,"No crickets - summer - in Kentucky - not one"}},
{"s12_tracks_dog_gone_quiet_023","night_watch",2,"reg=civilian,family|tmp=seasoned|hour=22,4|mood=fear",{1,"Sadie's under the truck and she won't come out for meat",2,"Storm coming, maybe",1,"Sky's clear as a bell, she's been under there since about eleven and she ain't made a sound"}},
{"s12_tracks_fires_answer_030","night_watch",2,"reg=civilian,worker|tmp=seasoned|hour=21,2|mood=grim",{1,"We lit a fire Tuesday - Wednesday there was one on the far ridge",2,"Folks like us",1,"Thursday there was three, we ain't lit one since and I'd like to keep it that way"}},
{"s12_tracks_bugs_on_the_porch_044","night_watch",2,"reg=civilian,family|tmp=seasoned|hour=21,3|mood=grim|world=building",{1,"The porch light's been on an hour and there ain't a moth on it",2,"Hm",1,"Hm is right, every July of my life that bulb's been a ball of bugs by nine o'clock"}},
{"s12_wave_waves_at_night_023","night_watch",2,"reg=civilian,family|tmp=seasoned|hour=22,4|mood=fear",{1,"Something out past the wire waved at me, at two in the morning, in the dark",2,"You waved back?",1,"I did - God help me, I did, before I thought about it - it waved again"}},
{"s12_wave_fence_at_night_045","night_watch",2,"reg=civilian,family|tmp=seasoned|hour=23,4|mood=grim",{1,"Nine of 'em out at the wire tonight and two are kids - they ain't sick, they're asking",2,"So what do we do?",1,"I'm stood here doing arithmetic about beans with two kids looking at me - I hate myself a little"}},
{"s13_law_oath_paper_001","oath",2,"reg=law|role=law_deputy,law_sergeant|tmp=seasoned|day=0,30",{1,"You remember the oath? I don't, I remember the county attorney's secretary taking my picture",2,"Support the Constitution of the United States and of this Commonwealth - Faithfully execute, that's the meat of it",1,"Faithfully execute what? District court ain't sat since Monday",2,"Then we execute the parts that still exist, which is me, you, and a Chevy with a bad water pump"}},
{"exp_outlaw_credit","old_business",2,"reg=outlaw|st=neutral,careful",{1,"Cousin owed me forty bucks - before this",2,"Bet you kept reminding him",1,"Every time he asked for another twenty",2,"Forty ain't bad, mine got me for three hundred"}},
{"exp_outlaw_badtruck","old_business",2,"reg=outlaw|st=neutral,careful|world=vehicle",{1,"Sold a truck once, had to hit the starter with a hammer",2,"You tell the buyer that?",1,"I left the hammer in it - what else did he want?",2,"Probably a truck that fucking started"}},
{"exp_crime_cardstock","old_business",2,"reg=crime|st=neutral,careful",{1,"Remember that guy? Gold writing on his business cards",2,"The consultant, consultant of what, he never said",1,"Good cards, I used one under a table leg for months",2,"Finally did some work, then"}},
{"exp_crime_remembering","old_business",2,"reg=crime|st=neutral,careful",{1,"How'd you remember his birthday? I can't remember my own half the time",2,"Wrote it down, same as everybody else's",1,"You got mine in there?",2,"You told me three different dates - which one's real?"}},
{"exp_crime_noprice","old_business",2,"reg=crime|st=neutral,careful",{1,"He said it wasn't about the money",2,"How much did he want?",1,"You're not even gonna let me finish?",2,"Fine, finish",1,"...Eight hundred",2,"There it is"}},
{"exp_law_goat","old_calls",2,"reg=law|st=neutral,careful,friendly",{1,"Remember that loose goat? Nobody's goat, all morning",2,"Then you said you'd sell it",1,"Three people showed up, all with pictures of different goats",2,"I'd forgotten the pictures - Jesus"}},
{"exp_law_badstatement","old_calls",2,"reg=law|st=neutral,careful,friendly|world=vehicle",{1,"Had a witness tell me the car was red - then blue, then maybe a truck",2,"Saw it on television, did he?",1,"No, he thought red was what I WANTED him to say",2,"Ah, shit, one of those statements"}},
{"exp_civ_wallpaper","old_home",2,"reg=civilian|st=friendly,neutral,careful|world=building",{1,"Whole damn weekend scraping wallpaper - those little yellow flowers, remember those?",2,"At your old place? Yeah",1,"Same stuff underneath, I mean EXACTLY the same fucking paper",2,"Oh, I'd have left it - put a couch in front of it"}},
{"exp_gang_oldcourt","old_neighborhood",2,"reg=gang|st=neutral,careful",{1,"That loose board at the gym, ball hit it and just died",2,"You always pushed me that side",1,"You always fell for it",2,"I KNEW you were doing something, son of a bitch"}},
{"s13_wire_lawful_order_001","order",3,"reg=military|role=soldier_nco,soldier,soldier_green|world=vehicle,cars",{1,"Sergeant, is that a lawful order?",2,"Say that again, but think about it first",1,"I'm asking - turn back vehicles, warning shots, then fire into the vehicle - is that lawful?",3,"It's on the card, it came down on a card",2,"A card ain't a law, neither is me saying it, which is exactly why he asked"}},
{"s13_wire_roe_card_002","order",2,"reg=military|tmp=veteran|world=vehicle",{1,"Read me the card again",2,"Warn - warn again - Disable the vehicle, then, quote, defend the line",1,"Defend the line, that's the part they left soft on purpose"}},
{"s13_wire_article_92_003","order",2,"reg=military|role=soldier_nco",{1,"You disobey and it's Article 92",2,"You obey the wrong one and it's a different article and a longer sentence",1,"You read the whole book, didn't you",2,"I read the parts with numbers in 'em, twice, in June, on a cot"}},
{"s13_wire_in_writing_004","order",2,"reg=military|mood=angry",{1,"I'll take that order in writing, sir",2,"You know how that sounds",1,"I know exactly how it sounds, I still want it on paper with your name at the bottom"}},
{"s13_wire_lt_wont_sign_005","order",3,"reg=military",{1,"Lieutenant wouldn't sign it",2,"He say why?",1,"Said he'd give it verbally in front of witnesses",3,"That's a no, that's a man telling you no in a long way"}},
{"s13_wire_kid_wont_fire_008","order",2,"reg=military|role=soldier_nco",{1,"Kerns wouldn't fire",2,"Did he refuse or did he freeze?",1,"Sat there with the safety on and his thumb laid across it",2,"Then he didn't refuse and he didn't freeze - he decided, we're calling it a malfunction"}},
{"s13_wire_took_his_rifle_009","order",2,"reg=military|tmp=fresh",{1,"Sergeant took my rifle off me",2,"Be glad, better him than the other way that goes",1,"I could have done it",2,"That's why he took it"}},
{"s13_wire_chaplain_asks_015","order",2,"reg=military|mood=grim",{1,"Chaplain asked me if I could do it",2,"Could you?",1,"I said I'd rather not find out, he said that ain't an answer, he was right"}},
{"s13_wire_nineteen_years_old_018","order",2,"reg=military|role=soldier_green",{1,"How old are you, Kerns?",2,"Nineteen, Sergeant",1,"I've got a nephew nineteen, he bags groceries at the Sav Rite",2,"That's what I did before drill weekend"}},
{"s13_wire_two_weeks_a_year_019","order",3,"reg=military|mood=angry",{1,"One weekend a month, two weeks a year, that's what the man at the mall told me",2,"Recruiter told me I'd learn diesel",3,"You did learn diesel",2,"I learned diesel, I did not learn this"}},
{"s13_wire_dozer_road_020","order",2,"reg=military|hour=4,9|world=road",{1,"They want the dozer to cut the road at first light",2,"Whose road?",1,"State road - nobody's, which is exactly how a fella gets told to cut it"}},
{"s13_wire_no_relief_021","order",2,"reg=military|role=soldier_nco",{1,"Post four's been on the line thirty-one hours",2,"Rotate 'em",1,"With who? Eleven men for three posts and two of them eleven are sick"}},
{"s13_wire_nco_says_no_023","order",3,"reg=military|role=soldier_nco|mood=angry",{1,"Sir, I'm not passing that one down",2,"Sergeant",1,"You want it done, walk out to the wire and tell 'em yourself - I'll stand right there with you",3,"He ain't coming out to the wire",1,"No, he ain't"}},
{"s13_wire_who_signs_024","order",2,"reg=military|tmp=veteran",{1,"Somebody's name has got to be on this",2,"Put mine",1,"You sure?",2,"My name's already on the duty roster and the ammo receipt - one more line won't change my week"}},
{"s13_wire_deputy_pulls_rank_038","order",3,"reg=military|world=road",{1,"Deputy come up to the wire and told me he's the law in this county",2,"What'd you tell him?",1,"I told him yes sir, and that the road is still shut",3,"He take that alright?",1,"Sat in his car twenty minutes with it running, then left - I don't think he had anywhere to be"}},
{"s13_wire_lt_young_042","order",2,"reg=military|tmp=veteran|world=vehicle",{1,"Lieutenant's twenty-four with a map and a flashlight and he is trying",2,"He's also wrong about the culvert",1,"He's wrong about the culvert - tell him at the truck, not in front of the posts"}},
{"s13_wire_oath_enlist_045","order",2,"reg=military|role=soldier_nco",{1,"I swore to obey the orders of the officers appointed over me",2,"You also swore to support and defend the Constitution, they put that part first",1,"You reckon somebody wrote it in that order on purpose?",2,"I reckon whoever wrote it knew exactly what he was doing - yeah"}},
{"s13_wire_nobody_relieved_049","order",1,"reg=military|role=soldier_nco|mood=grim",{1,"Nobody's been relieved, not one post, not once, since the sixth",1,"I rotate 'em between three holes so it feels like something's happening",1,"They know what I'm doing, they let me do it 'cause it makes me feel better, and they're kind"}},
{"s13_wire_end_of_order_050","order",3,"reg=military|role=soldier_nco|tmp=veteran",{1,"Alright, here's the order, and it's mine, not battalion's",1,"Nothing crosses without me looking at it, nobody fires without my voice, anybody turns around goes free",2,"And if battalion comes back up on the net?",1,"Then I stand up and answer for all three of them sentences",3,"Say 'em again, Sergeant, slow, I want to have 'em right"}},
{"s13_wire_nobody_villain_056","order",2,"reg=military|mood=sad",{1,"Folks out there think we're the bad ones",2,"Course they do, we're the ones with the wire",1,"I've got a cousin on the far side",2,"Everybody's got a cousin on the far side, post two, both of 'em do"}},
{"s13_wire_sergeant_major_059","order",2,"reg=military|tmp=veteran|hour=16,5|world=vehicle,road",{1,"A sergeant major come through in a humvee Saturday, stood on the road about a minute",2,"What'd he say?",1,"Told me my wire was sloppy, then shook my hand and said stay off the net after dark",2,"Which part you reckon was the real message?",1,"The handshake, he was not a handshake kind of man"}},
{"s13_wire_kerns_back_060","order",3,"reg=military|mood=warm|world=vehicle",{1,"Kerns come back up to the wire and asked for his rifle",2,"You give it to him?",1,"Asked him what he'd do if a truck came at him right now",3,"I said engine block and holler - twice, then holler again",1,"He got the rifle"}},
{"s13_mp_provost_gone_042","order",2,"reg=military|mood=grim",{1,"Who do we report to now? Provost marshal's office don't answer",2,"We report to the log, then whoever comes asking gets the log"}},
{"fw_ld4_topics_b_0032","outpost_farm",2,"reg=civilian,family,worker,rescue",{1,"The tomatoes are coming in",2,"Green?",1,"Red, red as lipstick, look at them",2,"Don't pick them yet",1,"I know, I'm just admiring"}},
{"fw_ld4_topics_b_0033","outpost_farm",2,"reg=civilian,family,worker,rescue",{1,"Something's eating the beans",2,"Deer?",1,"Rabbits",2,"Put up a scarecrow",1,"We did, they ate the scarecrow's hat"}},
{"fw_ld4_topics_b_0034","outpost_farm",2,"reg=civilian,family,worker,rescue",{1,"How many rows have we got?",2,"Six",1,"That's not enough",2,"It's what we can water"}},
{"fw_ld4_topics_b_0035","outpost_farm",2,"reg=civilian,family,worker,rescue",{1,"My hands are blistered",2,"Mine too",1,"I never thought I'd miss an office job",2,"I never thought I'd love dirt"}},
{"fw_ld4_topics_b_0036","outpost_farm",2,"reg=family",{1,"Papaw, when do the potatoes come up?",2,"In their own sweet time, child",1,"How long is that?",2,"As long as it takes, you can't rush a potato"}},
{"s10_farm_second_leaf_001","outpost_farm",2,"reg=civilian,worker|tmp=fresh,seasoned|day=15,200|mood=funny",{1,"Hill the dirt up to the second leaf, not over it",2,"I did taxes for twenty-two years, I don't know which one's the second leaf",1,"It's the one right after the first leaf",2,"Thank you, that clears up everything"}},
{"s10_farm_dress_right_beans_002","outpost_farm",3,"reg=military|day=20,300|mood=funny",{1,"Twelve years in the Army and I'm out here hoeing beans",2,"The Army's hoeing beans, you're just the part of it in this row",3,"Sergeant wants the rows dressed right, like a formation",1,"They're beans, they don't know what dress right is",3,"Then teach 'em, he's coming down the row with a tape measure"}},
{"s10_farm_spit_or_milk_003","outpost_farm",3,"reg=raider|tmp=predator|day=10,200|mood=funny",{1,"Cow's making that noise again",2,"She wants milking",1,"Then you milk her",2,"We ran off the man who knew how, that was sort of the hole in the plan",3,"Old man's wife is still down in the root cellar - go ask her",1,"She spit on me last time",3,"Spit or milk - pick one"}},
{"s10_farm_signs_in_the_feet_004","outpost_farm",3,"reg=family|day=20,200|hour=20,5|mood=warm",{1,"Mamaw says don't put the turnips in till the signs are in the feet",2,"The signs?",1,"In the almanac, when the moon's in the feet, you plant what grows down",3,"Almanac's from nineteen eighty-one",1,"She says the moon hasn't changed much since then"}},
{"s10_farm_leons_string_line_005","outpost_farm",2,"reg=civilian,family|tmp=seasoned|day=20,300|mood=sad",{1,"Whose string line is this, running out past the corn?",2,"Leon's, he was laying out a new fence row",1,"He's got a stake in every eight feet",2,"Then that's where the posts go, every eight feet, the way he had it"}},
{"s10_farm_manure_detail_006","outpost_farm",2,"reg=law|role=law_deputy,law_sheriff|day=20,300|mood=funny",{1,"Sheriff's office, manure detail, reporting for duty",2,"Don't you put that out over the radio",1,"Radio's dead, I'll put it on my headstone, nineteen years a deputy, finally did something useful"}},
{"s10_farm_blight_humming_007","outpost_farm",2,"reg=civilian,family|tmp=seasoned|day=30,150|mood=sad",{1,"Blight on the tomatoes, black spots all up the bottom leaves",2,"Pull the bad leaves and burn 'em, don't put 'em on the compost",1,"That's what Ellen always did, pulled the leaves and hummed the whole time",2,"Then hum"}},
{"s10_farm_hog_diversion_008","outpost_farm",3,"reg=civilian,family,worker|day=15,300|mood=funny",{1,"Hog's through the fence!",2,"Which way'd he go?",1,"Straight down the road at that bunch by the church",3,"Let him go, best diversion we ever had, and he's working for free",2,"That was two hundred pounds of Christmas",3,"Then say a nice word for him at Christmas"}},
{"s10_farm_tomato_grandma_009","outpost_farm",3,"reg=gang|day=20,200|mood=warm",{1,"Look at Dre with his little tomato plants, talking to 'em",2,"Say what you want, those are mine, the big one's named after my grandmother",3,"So Grandma gets eaten in August",2,"Grandma always did love feeding people, she'd be fine with it"}},
{"s10_farm_prison_crew_corn_010","outpost_farm",2,"reg=prison|day=15,300|mood=funny",{1,"Anybody here know a thing about corn?",2,"Me, four summers on the farm crew at the state pen",1,"Thought you hated the farm crew",2,"Hated every day of it, now I'm the most important man in camp, life's a riot"}},
{"s10_farm_fifty_days_011","outpost_farm",2,"reg=civilian,family|tmp=fresh,seasoned|day=25,60|mood=calm|world=snow",{1,"It's August - is it too late for beans?",2,"Bush beans take fifty days, we'll squeak in before frost",1,"And if we don't?",2,"Then we'll have a real nice-looking row of plants to look at in October"}},
{"s10_farm_old_seed_corn_012","outpost_farm",3,"reg=civilian,family,worker|tmp=seasoned|day=20,200|mood=funny",{1,"Seed corn out of the co-op is two years old - says so right on the sack",2,"Will it come up?",1,"Half of it, maybe, so we plant it twice as thick",3,"That's your answer for everything, twice as thick",1,"Worked on my gravy, worked on my marriage, near enough"}},
{"s10_farm_papaw_pear_013","outpost_farm",2,"reg=family|day=40,120|mood=sad|world=trees",{1,"Pears came in on the old tree",2,"They any good?",1,"Sweetest in years",2,"That's the tree we put Papaw under",1,"I know it, I ate one standing right there"}},
{"s10_farm_squash_wilts_with_me_014","outpost_farm",2,"reg=civilian,family,worker|tmp=seasoned|day=20,120|hour=10,18|mood=grim",{1,"Garden gets two buckets a day, people get the rest",2,"The squash is wilting",1,"So am I, the squash can wilt right along with me"}},
{"s10_farm_church_lawn_corn_015","outpost_farm",3,"reg=civilian,family|day=25,150|mood=funny",{1,"Deacon Hardy would've had a stroke, seeing corn on the church lawn",2,"Deacon Hardy had a stroke over a basketball hoop in the parking lot",3,"Well, the Lord hasn't said a word against it - corn's knee-high",1,"The Lord never had to mow that lawn"}},
{"s10_farm_tobacco_barn_trade_016","outpost_farm",3,"reg=military|day=15,200|mood=funny",{1,"Barn on the Harlow place still has last year's burley hanging in it",2,"That's worth more than ammunition right now",3,"Worth more than me",1,"That's a low bar, Specialist"}},
{"s10_farm_warm_egg_017","outpost_farm",3,"reg=worker,civilian|day=20,300|mood=funny",{1,"Eleven eggs today",2,"Twelve hens",1,"So somebody's slacking",2,"Or somebody's eating one raw on the walk back from the coop",3,"It was still warm, y'all would've done the same"}},
{"s10_farm_morning_beans_018","outpost_farm",1,"reg=family,civilian|tmp=seasoned|day=20,300|hour=5,10|mood=sad",{1,"Morning, beans - morning, peppers",1,"She talked to 'em every day, swore they grew better for it",1,"Can't prove it, can't prove it ain't so - morning, squash"}},
{"s10_farm_pot_or_jar_019","outpost_farm",3,"reg=outlaw|day=40,300|mood=calm",{1,"That corn is for eating",2,"That corn is for the still",3,"Split it, half for the pot, half for the jar",1,"Can't live on liquor",2,"Folks trade anything for a jar - ask me in January which half kept us fed"}},
{"s10_farm_potato_tires_020","outpost_farm",3,"reg=club|day=15,300|mood=funny",{1,"Stack three tires, fill 'em with dirt, drop the seed potatoes in",2,"Those are bike tires",1,"They're potato tires now, the rears hold more",3,"Not Dutch's old front tire, he'd come back and haunt the potatoes"}},
{"s10_farm_potato_bugs_kids_021","outpost_farm",2,"reg=family|day=20,120|mood=warm",{1,"Kids get a penny for every potato bug they pick",2,"What's a penny buy anybody now?",1,"Nothing, they don't know that yet - look at 'em go"}},
{"s10_farm_bullets_or_seed_022","outpost_farm",3,"reg=civilian,worker,family|tmp=seasoned|day=60,300|mood=grim",{1,"Trader at the gate wants the seed corn, offering a box of shotgun shells",2,"Shells keep us alive this week",3,"Seed keeps us alive next year",1,"Next year's a long way off",3,"So's the bottom of that box of shells - tell him no"}},
}
